<template><f7-page class="cy-mobile-surface"><f7-navbar title="主题外观" back-link="返回" /><main class="cy-page-body"><div class="cy-theme-options"><button v-for="theme in themes" :key="theme.value" :aria-pressed="settings.appSettings.theme===theme.value" @click="settings.setTheme(theme.value)"><div :class="['cy-theme-mini',theme.value]"><i /><i /><span /><span /><span /></div>{{ theme.name }}<f7-icon v-if="settings.appSettings.theme===theme.value" f7="checkmark_circle_fill" /></button></div><section class="cy-panel"><h3>主题色</h3><div class="cy-accent-options"><button v-for="color in colors" :key="color" :style="{background:color}" :aria-label="`主题色 ${color}`" :aria-pressed="experience.preferences.accent===color" @click="experience.set('accent',color)"><f7-icon v-if="experience.preferences.accent===color" f7="checkmark" /></button><input type="color" aria-label="自定义主题色" :value="experience.preferences.accent" @input="experience.set('accent',($event.target as HTMLInputElement).value)" /></div></section><f7-list strong inset><f7-list-item title="定时深色模式"><template #after><f7-toggle :checked="experience.preferences.nightSchedule" @toggle:change="experience.set('nightSchedule',$event)" /></template></f7-list-item><f7-list-input v-if="experience.preferences.nightSchedule" label="开始时间" type="time" :value="experience.preferences.nightStart" @change="experience.set('nightStart',($event.target as HTMLInputElement).value)" /><f7-list-input v-if="experience.preferences.nightSchedule" label="结束时间" type="time" :value="experience.preferences.nightEnd" @change="experience.set('nightEnd',($event.target as HTMLInputElement).value)" /></f7-list></main></f7-page></template>
<script setup lang="ts">import {useSettingsStore} from '@/stores/setting.ts';import {useLedgerExperienceStore} from '@/stores/ledgerExperience.ts';const settings=useSettingsStore(),experience=useLedgerExperienceStore(),themes=[{value:'light',name:'浅色'},{value:'dark',name:'深色'},{value:'auto',name:'跟随系统'}],colors=['#087f72','#497aac','#9c685f','#90764f','#7d709b','#525d62'];</script>
<style scoped>.cy-theme-options{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:15px 0 25px}.cy-theme-options>button{background:none;border:0;color:var(--cy-ink);font-size:13px;position:relative}.cy-theme-options>button>.icon{position:absolute;right:8px;bottom:-5px;color:var(--cy-accent);font-size:15px}.cy-theme-mini{height:152px;border:2px solid var(--cy-line);border-radius:12px;padding:14px 7px;display:flex;flex-wrap:wrap;gap:8px;align-content:flex-start;background:#f6f7f8;margin-bottom:12px}.cy-theme-options button[aria-pressed=true] .cy-theme-mini{border-color:var(--cy-accent)}.cy-theme-mini i{width:40%;height:28px;background:#dfeae7;border-radius:5px}.cy-theme-mini span{width:100%;height:18px;background:white;border-radius:5px}.cy-theme-mini.dark{background:#202933}.cy-theme-mini.dark span{background:#3d4854}.cy-theme-mini.dark i{background:#405c59}.cy-theme-mini.auto{background:linear-gradient(90deg,#f6f7f8 50%,#202933 50%)}.cy-accent-options{display:flex;flex-wrap:wrap;gap:15px;margin:20px 0 5px}.cy-accent-options button{border:0;width:32px;height:32px;border-radius:50%;color:white}.cy-accent-options .icon{font-size:18px}.cy-accent-options input{width:32px;height:32px;border:0;background:none}</style>
